/// <summary>
/// The <c>AVAKBVSetRequestStatusMan</c> class is the helper class for <c>BPs</c>
/// </summary>
class AVAKBVSetRequestStatusMan  extends RunBaseBatch
{
    DialogField                     dlgtransDate;
    boolean                         showQueryForm;
    boolean                         showDialog;

    KCS_KBVRequestStatus            kcs_KBVRequestStatus;
    DialogField                     dialogKBVRequestStatus;

    KCS_KBVDeclinedMemo             kcs_KBVDeclinedMemo;
    DialogField                     dialogKBVDeclinedMemo;

    DialogRunbase                   dialogRunbase;

    KCS_KBVRequestId                kcs_KBVRequestId;
    KCS_KBVRequestTable             kcs_KBVRequestTable;

    #define.CurrentVersion(1)
    #define.Version1(1)
    #localmacro.CurrentList
        kcs_KBVRequestStatus,
        kcs_KBVDeclinedMemo
    #endmacro

}

