/// <summary>
///    AVA <c>canGoBatch</c> method.
/// </summary>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
public boolean canGoBatch()
{
    return false;
}

/// <summary>
///    AVA <c>dialog</c> method.
/// </summary>
/// <returns>
///    <c>Object</c> as return value
/// </returns>
public Object dialog()
{
    DialogRunbase   dialog;
    DialogGroup     dialogGroup;

    dialog = super();

    kcs_KBVRequestTable     = kcs_KBVRequestTable::find(kcs_KBVRequestId);
    kcs_KBVRequestStatus    = kcs_KBVRequestTable.KCS_KBVRequestStatus;
    kcs_KBVDeclinedMemo     = kcs_KBVRequestTable.KCS_KBVDeclinedMemo;

    dialogGroup             = dialog.addGroup();
    dialogGroup.caption("@NDX:NXABuildingProjectStatus");
    dialogKBVRequestStatus  = dialog.addFieldValue(enumStr(KCS_KBVRequestStatus), kcs_KBVRequestStatus);
    dialogKBVDeclinedMemo   = dialog.addFieldValue(extendedtypestr(KCS_KBVDeclinedMemo), kcs_KBVDeclinedMemo);

    return dialog;
}

/// <summary>
///    AVA <c>getFromDialog</c> method.
/// </summary>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
public boolean getFromDialog()
{
    boolean ret;

    ret = super();

    kcs_KBVRequestStatus    = dialogKBVRequestStatus.value();
    kcs_KBVDeclinedMemo     = dialogKBVDeclinedMemo.value();

    return ret;
}

/// <summary>
///    AVA <c>new</c> method.
/// </summary>
protected void new ()
{
    super();
}

/// <summary>
///    AVA <c>pack</c> method.
/// </summary>
/// <returns>
///    <c>container</c> as return value
/// </returns>
public container pack()
{
    return [#CurrentVersion, #CurrentList];
}

/// <summary>
///    AVA <c>parmKCS_KBVRequestId</c> method.
/// </summary>
/// <param name="_kcs_KBVRequestId">
///    <c>KCS_KBVRequestId</c> as type
/// </param>
/// <returns>
///    <c>KCS_KBVRequestId</c> as return value
/// </returns>
public KCS_KBVRequestId parmKCS_KBVRequestId(KCS_KBVRequestId _kcs_KBVRequestId = kcs_KBVRequestId)
{
    kcs_KBVRequestId = _kcs_KBVRequestId;

    return kcs_KBVRequestId;
}

/// <summary>
///    AVA <c>run</c> method.
/// </summary>
void run()
{
    KCS_KBVRequestTable locKCS_KBVRequestTable;
    CompanyInfo         locCompanyInfo;

    locKCS_KBVRequestTable   = KCS_KBVRequestTable::find(this.parmKCS_KBVRequestId());
    locCompanyInfo           = CompanyInfo::find();

    if (locKCS_KBVRequestTable.RecId)
    {
        locKCS_KBVRequestTable.selectForUpdate(true);
        locKCS_KBVRequestTable.KCS_KBVDeclinedMemo  = kcs_KBVDeclinedMemo;
        locKCS_KBVRequestTable.KCS_KBVRequestStatus = kcs_KBVRequestStatus;

        if(     locKCS_KBVRequestTable.KCS_KBVRequestStatus == KCS_KBVRequestStatus::Refused)
        {
            locKCS_KBVRequestTable.KCS_KBVDeclinedBy    = HcmWorkerLookup::currentWorker();
            locKCS_KBVRequestTable.KCS_KBVDeclinedDate  = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
        }
        else
        {
            locKCS_KBVRequestTable.KCS_KBVDeclinedBy    = 0;
            locKCS_KBVRequestTable.KCS_KBVDeclinedDate  = dateNull();
        }

        if(locKCS_KBVRequestTable.validateWrite())
        {
            ttsbegin;
            locKCS_KBVRequestTable.write();
            ttscommit;
        }
    }
}

