/// <summary>
///    AVA <c>unpack</c> method.
/// </summary>
/// <param name="packedClass">
///    <c>container</c> as type
/// </param>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
public boolean unpack(container packedClass)
{
    Version     version;

    version = RunBase::getVersion(packedClass);

    switch (version)
    {
        case #CurrentVersion:
            [version,#CurrentList] = packedClass;
            break;

        default:
            return false;
    }

    return true;
}

/// <summary>
///    AVA <c>construct</c> method.
/// </summary>
/// <returns>
///    <c>AVAKBVSetRequestStatusMan</c> as return value
/// </returns>
server static AVAKBVSetRequestStatusMan construct()
{
    return new AVAKBVSetRequestStatusMan();
}

/// <summary>
///    AVA <c>main</c> method.
/// </summary>
/// <param name="args">
///    <c>Args</c> as type
/// </param>
static void main(Args args)
{
    Common                      record      = args.record();
    KCS_KBVRequestTable         kcs_KBVRequestTable;
    AVAKBVSetRequestStatusMan   avaKBVSetRequestStatusMan;

    if (!args)
    {
        throw error("@SYS25407");
    }

    if (!record.TableId == tablenum(KCS_KBVRequestTable))
    {
        throw error("@NDX:NXAPassedWrongRecord");
    }
    else
    {
        kcs_KBVRequestTable         = record;

        avaKBVSetRequestStatusMan   = AVAKBVSetRequestStatusMan::construct();

        avaKBVSetRequestStatusMan.parmKCS_KBVRequestId(kcs_KBVRequestTable.KCS_KBVRequestID);

        if (avaKBVSetRequestStatusMan.prompt())
        {
            //avaKBVSetRequestStatusMan.run();    // BP: changed to avaKBVSetRequestStatusMan.runOperation()
            avaKBVSetRequestStatusMan.runOperation();

            if (kcs_KBVRequestTable)
            {                    
                /* KCS_KBVClosedBy relation to worker was not refreshed with this implementation
                kcs_KBVRequestTable.dataSource().reread();
                kcs_KBVRequestTable.dataSource().refresh();
                */
                int pos =  FormDataUtil::getFormDataSource(kcs_KBVRequestTable).getPosition();
                FormDataUtil::getFormDataSource(kcs_KBVRequestTable).research(); //true);
                FormDataUtil::getFormDataSource(kcs_KBVRequestTable).setPosition(pos);
            }
        }
    }
}

